using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_set<long long> alone;
    for (int i = 0; i < n; i++) {
        if (alone.count(a[i])) alone.erase(a[i]);
        else alone.insert(a[i]);
    }
    cout << *alone.begin() << "\n";

    return 0;
}

